// The HTTP node splits a JSON array into items; collect them back.
const ev = $input.all().map(i => i.json).filter(e => e && e.id);
if (!ev.length) return [];
const short = a => a ? a.slice(0, 6) + '...' + a.slice(-4) : '?';
// Official $FLAG: everything. Dry-run tokens: only the interesting stuff.
const DRY = new Set(['copycat', 'first_trade', 'sandwich', 'sniper', 'bundle']);
const keep = ev.filter(e => e.type === 'copycat' || e.official || DRY.has(e.type));
const groups = {};
for (const e of keep) {
  const k = (e.type === 'copycat' ? 'COPYCAT' : (e.symbol || short(e.token)) + (e.official ? ' (OFFICIAL)' : '')) + '|' + e.type;
  (groups[k] = groups[k] || []).push(e);
}
const label = { sniper: 'sniper buy', bundle: 'bundled buy', sandwich: 'sandwich attack', first_trade: 'first trade', whale: 'whale trade', zero_value_transfer: 'zero-value transfer (poisoning pattern)', copycat: 'copycat token' };
const lines = [];
for (const [k, list] of Object.entries(groups)) {
  const [tok, type] = k.split('|');
  lines.push(`🚩 ${tok}: ${list.length} ${label[type] || type}${list.length > 1 ? 's' : ''}`);
  for (const e of list.slice(0, 3)) {
    const x = e.detail || {};
    if (type === 'copycat') lines.push(`   ${x.symbol} "${x.name}" ${x.url || ''}`);
    else if (type === 'sniper') lines.push(`   ${short(e.wallet)} bought ${x.blocks_after_deploy} blocks after launch for ${Number(x.paid).toFixed(4)} ETH`);
    else if (type === 'bundle') lines.push(`   ${(x.wallets || []).length} wallets back-to-back in block ${x.block}, ~${Number((x.paid_each || [0])[0]).toFixed(4)} ETH each`);
    else if (type === 'sandwich') lines.push(`   ${short(x.attacker)} sandwiched ${short(x.victim)} https://basescan.org/tx/${e.tx}`);
    else if (type === 'first_trade') lines.push(`   ${x.side} by ${short(e.wallet)}, ${x.blocks_after_deploy} blocks after launch`);
    else if (type === 'whale') lines.push(`   ${x.side} ${Number(x.amount).toLocaleString()} tokens for ${x.paid} ETH by ${short(e.wallet)}`);
    else lines.push(`   ${short(e.wallet)} https://basescan.org/tx/${e.tx}`);
  }
}
const ids = ev.map(e => e.id);
let text = lines.join('\n');
if (text.length > 3900) text = text.slice(0, 3900) + '\n...more in the daily email';
return [{ json: { text, send: lines.length > 0, ids } }];
